/dsh-sandbox-policy\": \"^0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-scope\": \"^0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-session\": \"^0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-skill\": \"^0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-skill-filesystem\": \"^0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-system-prompt\": \"^0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-tools\": \"^0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-user-approval\": \"^0.2.0-rc.2\",\n    \"@deepseek-ai/schemastery\": \"^3.18.4\",\n    \"@types/node\": \"^26.6.5\",\n    \"typescript\": \"^7.0.2\"\n  },\n  \"author\": {\n    \"name\": \"Amethyst Luna\",\n    \"url\": \"https://github.com/AmethystLuna\"\n  },\n  \"license\": \"MIT\",\n  \"repository\": \"https://github.com/AmethystLuna/logicprobe\",\n  \"funding\": {\n    \"type\": \"custom\",\n    \"url\": \"https://afdian.com/a/amethystluna\"\n  },\n  \"keywords\": [\n    \"verification\",\n    \"fact-check\",\n    \"design-review\",\n    \"plan-review\",\n    \"state-machine\",\n    \"logic-verification\",\n    \"adversarial\",\n    \"refactoring\",\n    \"model-checking\",\n    \"agentskills\",\n    \"plugin\",\n    \"dsh\"\n  ],\n  \"engines\": {\n    \"node\": \">=20\"\n  }\n}\n"
