      "content": "/**\n * logicprobe — DeepSeek Harness native plugin for the Logic Probe toolbox.\n * Injects the session-start gate text (what this plugin checks, the routing to\n * the skills, the tool list, how to read a report)\n * into the first model step of every agent session, mirroring the SessionStart\n * hook the Claude Code plugin installs.\n * The skill ships in this package's `skills/` directory and is registered at\n * apply time into dsh's `ctx.skills` registry through the standard filesystem\n * provider, so it appears in every session catalog without a manual copy step.\n *\n * Injection listens on agent/pre-step and appends the gate to the FIRST\n * model step that runs, once per session (guarded by the session's durable\n * history). Session-start inbox injection was dropped: a blank-session preset\n * switch (agentPreset.select -> recompose) can clear the inbox before the\n * first step, losing the gate for the whole session. The pre-step decision is\n * the durable path - anchored/bootstrap presets that strip first-step injected\n * reminders (skill catalog, AGENTS.md, gate plugins) simply defer this message\n * to the first step after their promotion, and the history guard re-injects it\n * there. The default gate text is the dsh-native adaptation of\n * `hooks/session-start-content.md`. Both are a guide to calling the tools: what\n * this plugin checks, the routing to the sibling skills, the tool list, and how to\n * read a report. The Red Flags table is enforcement scaffolding and lives in the\n * skill body instead, where a session that needs it can load it.\n * They stay in sync. Method, doctrine and per-domain detail live in the skills\n * and their references, not here. Deployments override via Config.\n *\n * @module logicprobe-dsh\n */\n\nimport { fileURLToPath } from 'node:url'\nimport type { Context, Volatile } from '@deepseek-ai/cordis'\nimport z from '@deepseek-ai/schemastery'\nimport { createUserMessage } from '@deepseek-ai/dsh-llm'\nimport type { ContextFormed } from '@deepseek-ai/dsh-llm'\nimport type { Session, UserMessage } from '@deepseek-ai/dsh-session'\nimport type { HostCordisInspectProviderRegistration } from '@deepseek-ai/dsh-cordis-host-runner'\nimport type { AssembleContext, PromptContext } from '@deepseek-ai/dsh-system-prompt'\nimport { FileSystemSkillProvider } from '@deepseek-ai/dsh-skill-filesystem'\nimport { logicProbeVerifyTool } from './tool.js'\nimport { logicProbeDataModelVerifyTool, DATA_ENGINE_SCHEMA_VERSION } from './data-tool.js'\nimport { logicProbeConcurrencyScanTool } from './concurrency-tool.js'\nimport { logicProbeComposeTool } from './compose-tool.js'\nimport { logicProbeExportTool } from './export-tool.js'\nimport { logicProbeUmlTool } from './uml-tool.js'\nimport { logicProbeStructureTool } from './structure-tool.js'\nimport { logicProbeReportDiffTool } from './report-diff-tool.js'\nimport { ENGINE_SCHEMA_VERSION } from './engine.js'\n\n// DSH 0.1.7-alpha.1 (session format v4) retires the shared\n// `{ kind: 'plugin', plugin }` wrapper: native admission rejects it in every\n// declared durable message slot, and the official v3-to-v4 migration rewrites\n// those historical rows to `plugin:<name>`. Declaring the producer-owned kind\n// here keeps the write path and the history guard on one identity, and still\n// compiles against the earlier releases that only declare `plugin`.\ndeclare module '@deepseek-ai/dsh-llm' {\n  interface MessageSourceMap {\n    'plugin:logicprobe': { kind: 'plugin:logicprobe' } & ContextFormed\n  }\n}\n\nexport const name = 'logicprobe'\n\n// Skills are contributed through the registry service, which dsh-base always\n// mounts before bundle rows such as this one apply.\nexport const inject = ['skills']\n\n// Absolute path of the package's shipped skills directory. `lib/index.js`\n// lives one level below the package root, so `../skills` from the module URL\n// lands on `<package>/skills` regardless of where the package was installed.\nconst SKILLS_DIR = fileURLToPath(new URL('../skills', import.meta.url))\n\nconst GATE_PLUGIN_ID = 'logicprobe'\n\n/** Producer-owned message source kind declared in `MessageSourceMap` above. */\nconst GATE_SOURCE_KIND: 'plugin:logicprobe' = 'plugin:logicprobe'\n\nexport type InteractionMode = 'ask' | 'auto' | 'follow-approval'\n\nconst DEFAULT_GATE_CONTENT = `\n<EXTREMELY_IMPORTANT>\nPlugin logicprobe is active. It checks claims about designs and code: facts against the source, behaviour as an executable model.\n\n**Unsure whether a check applies?** Load \\`logicprobe\\` first. It is the entry point: it owns the doctrine, the model schema, the depth rules and the routing to its siblings.\n\n**Load the skill that matches the claim**: \\`logicprobe\\` (entry point; claim and behaviour checks), \\`logicprobe-uml\\` (diagrams), \\`logicprobe-structure\\` (architecture, dependencies), \\`logicprobe-concurrency\\` (concurrency claims), \\`logicprobe-datamodel\\` (data models, migrations).\n\n**Tools** (dsh):\n\n- \\`logicprobe_verify\\` — state machines: structural checks, adversarial probes, budgets, deadlines, before/after regression.\n- \\`logicprobe_datamodel_verify\\` — data models and migrations: structure, migration coverage, copy consistency, rollback, before/after data.\n- \\`logicprobe_compose_verify\\` — two or more machines: deadlock, and a rendezvous that never fires.\n- \\`logicprobe_concurrency_scan\\` — finds concurrency claims and routes them. It proves nothing about concurrency.\n- \\`logicprobe_export\\` — UPPAAL, TLA+, PRISM and SPIN input from a verified model.\n- \\`logicprobe_uml\\` — render, parse or review a UML diagram.\n- \\`logicprobe_structure_verify\\` — dependency review of a structure diagram, at one level or several.\n- \\`logicprobe_report_diff\\` — baseline against current: what a change added, removed or changed.\n\n**Read a report**: gate on \\`verdict\\` (\\`pass\\`, \\`pass_with_findings\\`, \\`fail\\`), never on \\`ok\\`. Reports carry \\`verdictReason\\`, \\`hashes\\` and \\`nextSteps\\`. Keys starting with \\`_\\` are notes: ignored, and left out of the model hash. A tool prints the report body: passing checks stay in the inventory line, repeated facts are grouped, and warning evidence is omitted — pass \\`reportView: \"full\"\\` only when you need the structured report itself, which \\`logicprobe_report_diff\\` consumes.\n\n</EXTREMELY_IMPORTANT>\n`\n\n/** A schemastery field that may or may not carry `.volatile()`. */\ninterface LiveField {\n  volatile?: () => unknown\n}\n\n/**\n * Declare a field as live where this host's schemastery can — `.volatile()`\n * arrived in 3.18.3 — and leave it an ordinary field where it cannot.\n *\n * The fallback is load-bearing, not defensive padding. `Config` below is built\n * while this module is still being evaluated, so an unconditional `.volatile()`\n * on a host shipping schemastery 3.18.2 (measured: dsh 0.1.5-rc.2 and\n * 0.1.5-rc.3) throws during import; the loader entry then fails and takes the\n * WHOLE plugin tree — and the host's boot — down with it. Degrading costs only\n * the Plugins-page switch, because the settings service projects nothing but\n * fields under a `.volatile()` node; skills, tools and the gate injection are\n * untouched. The returned schema keeps the plain field's static type; the\n * `Config` interface below carries the union the host actually hands over.\n */\nfunction live<T>(field: T): T {\n  const probe = field as T & LiveField\n  return typeof probe.volatile === 'function' ? (probe.volatile() as T) : field\n}\n\nexport interface Config {\n  /**\n   * The injection switch the Web client's Plugins page edits live: a `Volatile`\n   * reference on a host whose schemastery supports one, an ordinary boolean on a\n   * host that predates `.volatile()`. Read it through {@link injectionEnabled},\n   * which accepts both shapes.\n   */\n  enabled: Volatile<boolean> | boolean\n  gateContent: string\n  interaction: InteractionMode\n}\n\nexport const Config = z.object({\n  // Live so the Web Plugins page can flip the gate injection inside a running\n  // session: dsh's settings service projects ONLY fields under a `.volatile()`\n  // node and rejects writes to every other path. The price is that the injection\n  // reads the reference per step instead of deciding once at mount, which is also\n  // what lets a toggle take effect without remounting the row.\n  enabled: live(z.boolean().default(true)),\n  gateContent: z.string().default(DEFAULT_GATE_CONTENT),\n  interaction: z.union(['ask', 'auto', 'follow-approval']).default('follow-approval'),\n})\n\n/**\n * Read the injection switch as a boolean, whichever shape this host produced.\n * @param config - the resolved plugin configuration.\n * @returns whether the gate may be injected.\n */\nfunction injectionEnabled(config: Config): boolean {\n  const value = config.enabled\n  return typeof value === 'boolean' ? value : value.get()\n}\n\nfunction gateMessage(text: string): UserMessage {\n  return createUserMessage({\n    content: [{ type: 'text', text }],\n    // `form` omitted — an undeclared context is the documented default.\n    source: { kind: GATE_SOURCE_KIND },\n  })\n}\n\ninterface SessionEventLike {\n  type: string\n  data?: Record<string, unknown>\n}\n\n/**\n * Minimum session-store surface this plugin reads. DSH 0.1.2-alpha.4 replaced\n * the `Session.events` getter with on-demand reads (`seq`, `eventAt()`,\n * `snapshotEvents()`); releases up to 0.1.2-alpha.3 expose `events` as the\n * full log snapshot. Read through a structural union so one build serves every\n * declared DSH release.\n */\ninterface SessionEventSource {\n  events?: readonly SessionEventLike[]\n  snapshotEvents?: () => readonly SessionEventLike[]\n}\n\nfunction readSessionEvents(session: Session): readonly SessionEventLike[] {\n  const source = session as unknown as SessionEventSource\n  if (typeof source.snapshotEvents === 'function') {\n    const snapshot = source.snapshotEvents()\n    if (Array.isArray(snapshot)) return snapshot\n  }\n  if (Array.isArray(source.events)) return source.events\n  return []\n}\n\nfunction lastApprovalPolicy(session: Session): 'ask' | 'never' | undefined {\n  const events = readSessionEvents(session)\n  for (let index = events.length - 1; index >= 0; index -= 1) {\n    const event = events[index]\n    if (event.type === 'approval/policy') {\n      return event.data?.policy === 'never' ? 'never' : 'ask'\n    }\n  }\n  return undefined\n}\n\nfunction planModeActive(session: Session): boolean {\n  const events = readSessionEvents(session)\n  for (let index = events.length - 1; index >= 0; index -= 1) {\n    const event = events[index]\n    if (event.type === 'plan/mode') return event.data?.active === true\n  }\n  return false\n}\n\nfunction resolveInteraction(config: Config, session: Session): 'ask' | 'auto' {\n  if (config.interaction === 'ask' || config.interaction === 'auto') return config.interaction\n  return lastApprovalPolicy(session) === 'never' ? 'auto' : 'ask'\n}\n\nfunction modeContextText(config: Config, session: Session): string {\n  const interaction = resolveInteraction(config, session)\n  const lines = [\n    'logicprobe: tools — `logicprobe_verify` (state machines), `logicprobe_datamodel_verify` (data models, migrations), `logicprobe_compose_verify` (two or more machines), `logicprobe_concurrency_scan` (finds concurrency claims, proves nothing), `logicprobe_export` (UPPAAL, TLA+, PRISM, SPIN), `logicprobe_uml` (render, parse, review UML), `logicprobe_structure_verify` (dependency diagrams, one or several levels), `logicprobe_report_diff` (baseline vs current).',\n    'logicprobe: gate on `verdict`, never on `ok`. Reports carry `verdictReason`, `hashes` and `nextSteps`.',\n    interaction === 'auto'\n      ? 'logicprobe interaction=auto: do NOT call ask_user_question for model confirmation; run round-trip validation of the extracted transition table and mark the result UNCONFIRMED.'\n      : 'logicprobe interaction=ask: show the extracted transition table and get user confirmation before running verification.',\n  ]\n  if (planModeActive(session)) {\n    lines.push('Plan mode active: before exit_plan_mode, run logicprobe Phase 0 and append the \"## Plan Verification\" block to the plan file.')\n  }\n  return lines.join(' ')\n}\n\ninterface ToolRegistryLike {\n  register(definition: unknown): () => void\n}\n\ninterface SystemPromptLike {\n  context(contribution: PromptContext): () => void\n}\n\n/**\n * Model-visible catalog entry (cordis_inspect_list / cordis_inspect_query):\n * lets the model read this plugin's runtime status without guessing. Mirrors\n * the registration pattern of the official dsh-tool-cordis host providers.\n */\nfunction inspectProvider(config: Config, isToolRegistered: () => boolean, isDataToolRegistered: () => boolean, isConcurrencyToolRegistered: () => boolean, isComposeToolRegistered: () => boolean, isExportToolRegistered: () => boolean, isUmlToolRegistered: () => boolean, isStructureToolRegistered: () => boolean, isReportDiffToolRegistered: () => boolean): HostCordisInspectProviderRegistration {\n  return {\n    manifest: {\n      id: 'logicprobe',\n      description: 'Session-start gate injection and native verification tooling for the Logic Probe toolbox. The gate is a guide to calling the tools: what the plugin checks, the routing to the sibling skills, the tool list, and how to read a report. Doctrine and per-domain detail live in the skills.',\n      methods: [\n        {\n          name: 'status',\n          description: 'Read gate injection status, interaction mode, tool registration state, and engine schema version.',\n          inputSchema: {\n            type: 'object',\n            properties: {},\n            additionalProperties: false,\n          },\n          outputSchema: {\n            type: 'object',\n            description: 'Gate-injection plugin status.',\n            properties: {\n              enabled: { type: 'boolean', description: 'Whether the gate folds into the first model step.' },\n              gateContentLength: { type: 'integer', description: 'Length in characters of the injected gate text.' },\n              interaction: { type: 'string', enum: ['ask', 'auto', 'follow-approval'], description: 'Configured interaction mode. follow-approval resolves per session from approval/policy.' },\n              toolRegistered: { type: 'boolean', description: 'Whether the logicprobe_verify tool is registered on ctx.tools.' },\n              dataToolRegistered: { type: 'boolean', description: 'Whether the logicprobe_datamodel_verify tool is registered on ctx.tools.' },\n              concurrencyToolRegistered: { type: 'boolean', description: 'Whether the logicprobe_concurrency_scan tool is registered on ctx.tools.' },\n              composeToolRegistered: { type: 'boolean', description: 'Whether the logicprobe_compose_verify tool is registered on ctx.tools.' },\n              exportToolRegistered: { type: 'boolean', description: 'Whether the logicprobe_export tool is registered on ctx.tools.' },\n              umlToolRegistered: { type: 'boolean', description: 'Whether the logicprobe_uml tool (UML modelling + modelling review) is registered on ctx.tools.' },\n              structureToolRegistered: { type: 'boolean', description: 'Whether the logicprobe_structure_verify tool (structure-diagram / dependency review) is registered on ctx.tools.' },\n              reportDiffToolRegistered: { type: 'boolean', description: 'Whether the logicprobe_report_diff tool (baseline report comparison) is registered on ctx.tools.' },\n              engineSchemaVersion: { type: 'integer', description: 'Model schema version the bundled state-machine verification engine accepts.' },\n              dataEngineSchemaVersion: { type: 'integer', description: 'Model schema version the bundled data-model verification engine accepts.' },\n            },\n            required: ['enabled', 'gateContentLength', 'interaction', 'toolRegistered', 'dataToolRegistered', 'concurrencyToolRegistered', 'composeToolRegistered', 'exportToolRegistered', 'umlToolRegistered', 'structureToolRegistered', 'reportDiffToolRegistered', 'engineSchemaVersion', 'dataEngineSchemaVersion'],\n            additionalProperties: false,\n          },\n        },\n      ],\n    },\n    query: async (method) => {\n      if (method === 'status') {\n        return {\n          enabled: injectionEnabled(config),\n          gateContentLength: config.gateContent.length,\n          interaction: config.interaction,\n          toolRegistered: isToolRegistered(),\n          dataToolRegistered: isDataToolRegistered(),\n          concurrencyToolRegistered: isConcurrencyToolRegistered(),\n          composeToolRegistered: isComposeToolRegistered(),\n          exportToolRegistered: isExportToolRegistered(),\n          umlToolRegistered: isUmlToolRegistered(),\n          structureToolRegistered: isStructureToolRegistered(),\n          reportDiffToolRegistered: isReportDiffToolRegistered(),\n          engineSchemaVersion: ENGINE_SCHEMA_VERSION,\n          dataEngineSchemaVersion: DATA_ENGINE_SCHEMA_VERSION,\n        }\n      }\n      return null\n    },\n  }\n}\n\nexport function apply(ctx: Context, config: Config): void {\n  // Optional services are registered opportunistically; base-bundle rows can\n  // mount after this row applies, so registration is retried on the first\n  // agent/pre-step — by then the app is fully booted.\n  let providerRegistered = false\n  let toolRegistered = false\n  let dataToolRegistered = false\n  let concurrencyToolRegistered = false\n  let composeToolRegistered = false\n  let exportToolRegistered = false\n  let umlToolRegistered = false\n  let structureToolRegistered = false\n  let reportDiffToolRegistered = false\n  let modeContextRegistered = false\n  const registerProvider = (): void => {\n    if (providerRegistered) return\n    const inspect = ctx.get('cordisInspect')\n    if (inspect === undefined) return\n    try {\n      ctx.effect(() => inspect.register(inspectProvider(config, () => toolRegistered, () => dataToolRegistered, () => concurrencyToolRegistered, () => composeToolRegistered, () => exportToolRegistered, () => umlToolRegistered, () => structureToolRegistered, () => reportDiffToolRegistered)), 'logicprobe: inspect provider')\n      providerRegistered = true\n    } catch (err) {\n      console.warn('[logicprobe] inspect provider registration failed', err)\n    }\n  }\n  const registerTool = (): void => {\n    if (toolRegistered) return\n    const tools = ctx.get('tools') as ToolRegistryLike | undefined\n    if (tools === undefined) return\n    try {\n      ctx.effect(() => tools.register(logicProbeVerifyTool), 'logicprobe: verify tool')\n      ctx.effect(() => tools.register(logicProbeDataModelVerifyTool), 'logicprobe: data verify tool')\n      ctx.effect(() => tools.register(logicProbeConcurrencyScanTool), 'logicprobe: concurrency scan tool')\n      ctx.effect(() => tools.register(logicProbeComposeTool), 'logicprobe: compose tool')\n      ctx.effect(() => tools.register(logicProbeExportTool), 'logicprobe: export tool')\n      ctx.effect(() => tools.register(logicProbeUmlTool), 'logicprobe: uml tool')\n      ctx.effect(() => tools.register(logicProbeStructureTool), 'logicprobe: structure tool')\n      ctx.effect(() => tools.register(logicProbeReportDiffTool), 'logicprobe: report diff tool')\n      toolRegistered = true\n      dataToolRegistered = true\n      concurrencyToolRegistered = true\n      composeToolRegistered = true\n      exportToolRegistered = true\n      umlToolRegistered = true\n      structureToolRegistered = true\n      reportDiffToolRegistered = true\n    } catch (err) {\n      console.warn('[logicprobe] logicprobe_verify/logicprobe_datamodel_verify tool registration failed', err)\n    }\n  }\n  const registerModeContext = (): void => {\n    if (modeContextRegistered) return\n    const systemPrompt = ctx.get('systemPrompt') as SystemPromptLike | undefined\n    if (systemPrompt === undefined) return\n    try {\n      ctx.effect(() => systemPrompt.context({\n        name: 'logicprobe:mode',\n        order: 118,\n        text: (context: AssembleContext) => {\n          const agent = (context as AssembleContext & { agent?: { session: Session } }).agent\n          if (agent === undefined) return ''\n          return modeContextText(config, agent.session)\n        },\n      }), 'logicprobe: system prompt context')\n      modeContextRegistered = true\n    } catch (err) {\n      console.warn('[logicprobe] system prompt context registration failed', err)\n    }\n  }\n  const registerIntegrations = (): void => {\n    registerProvider()\n    registerTool()\n    registerModeContext()\n  }\n  registerIntegrations()\n  // Ship the bundled skill through the registry: reuse the standard\n  // filesystem provider over this package's own `skills/` directory, so\n  // catalog discovery, frontmatter parsing, and SKILL.md loading behave\n  // exactly like project/user skills while the plugin stays self-contained.\n  // Registration lands in the global registry layer (this row mounts at the\n  // profile root), so every agent preset sees the skill. `registerProvider`\n  // returns the effect disposer; its teardown unregisters and invalidates.\n  ctx.skills.registerProvider((control) => {\n    return new FileSystemSkillProvider(ctx, control, {\n      providerName: 'logicprobe',\n      includeDefaultRoots: false,\n      customSkillDirs: [SKILLS_DIR],\n    })\n  })\n  // Injection listens unconditionally, including while the switch is off: the\n  // switch is volatile, so `apply` runs once and the value behind it can turn on\n  // later from the Web Plugins page. Returning early on a false value here would\n  // freeze that decision for the lifetime of the mount, and turning the switch\n  // back on could never take effect without a profile restart.\n  //\n  // Inject the gate once per session on the FIRST model step that runs,\n  // instead of at session-start: session-start injection lands in the agent's\n  // inbox, which a blank-session preset switch (agentPreset.select ->\n  // recompose) can clear before the first step - the gate would then be lost\n  // for the whole session. The pre-step decision is the durable path a\n  // first-step injection takes: the gate is appended to the first step's\n  // decision and enters session history there, so every later step (and a\n  // resume) skips it. Anchored/bootstrap presets that strip first-step\n  // injected reminders (skill catalog, AGENTS.md, gate plugins) simply defer\n  // this message to the first step after their promotion - the history guard\n  // re-injects it there, so the gate still lands exactly once per session.\n  ctx.on('agent/pre-step', async ({ agent }, next) => {\n    const decision = await next()\n    if (decision.kind === 'reject') return decision\n    registerIntegrations()\n    if (!injectionEnabled(config)) return decision\n    if (gateInHistory(agent.session)) return decision\n    return {\n      kind: 'enter',\n      messages: [...decision.messages, gateMessage(config.gateContent)],\n    }\n  })\n}\n\n/**\n * Whether the gate already entered this session's durable history. The\n * pre-step listener re-appends the gate until it does; once a step committed\n * it, every later step (and a resume of a session that kept it) skips the\n * injection. A session whose gate was dropped before any step ran (e.g. an\n * inbox cleared by a blank-session preset switch) simply re-injects on the\n * first step that runs.\n */\nfunction gateInHistory(session: Session): boolean {\n  return readSessionEvents(session).some((event) => {\n    if (event.type !== 'user/message') return false\n    const source = event.data?.source as { kind?: string; plugin?: string } | undefined\n    if (source === undefined) return false\n    // The v4 producer-owned kind, plus the pre-v4 wrapper this bundle wrote\n    // before DSH 0.1.7-alpha.1 retired it.\n    return source.kind === GATE_SOURCE_KIND\n      || (source.kind === 'plugin' && source.plugin === GATE_PLUGIN_ID)\n  })\n}\n"
    },
