    {
      "path": "src/concurrency-tool.ts",
      "content": "import { defineTool } from '@deepseek-ai/dsh-tools'\nimport type { JsonValue } from './json-value.js'\nimport { runConcurrencyScan } from './concurrency.js'\nimport { renderReportText } from './report-view.js'\n\nexport const LOGICPROBE_CONCURRENCY_SCAN_TOOL_NAME = 'logicprobe_concurrency_scan'\n\n/**\n * Model-visible DSH tool that mines design documents/plans for concurrency-related\n * claims and risk keywords. It does not prove concurrency safety; it flags terms\n * such as \"thread-safe\", \"lock-free\", \"race condition\", \"atomic\", \"mutex\", etc.,\n * so the model can either provide dedicated evidence or mark the claim unverified.\n */\nexport const logicProbeConcurrencyScanTool = defineTool({\n  name: LOGICPROBE_CONCURRENCY_SCAN_TOOL_NAME,\n  description:\n    'Scan a document or plan text for concurrency risk points. Use ONLY after confirming the target actually has concurrency requirements or behavior (threads, async tasks, interrupts, shared state, parallel execution). If the target is purely sequential, do not call this tool. Returns findings for keywords like thread-safe, lock-free, wait-free, data race, race condition, atomic, synchronized, mutex, semaphore, spinlock, shared variable, shared memory, reentrant, interrupt-safe, ISR, IRQ, NMI, critical section, disable_irq/enable_irq. Absolute claims (thread-safe, lock-free, no data race, interrupt-safe, ISR-safe) are flagged as errors requiring dedicated verification, and each carries suggestions naming the analysis to run instead (TSan/Helgrind, CBMC, TLA+, or RTOS-aware interrupt analysis). logicprobe does not prove concurrency safety.',\n  parameters: {\n    text: {\n      type: 'string',\n      required: true,\n      description: 'Document or plan text to scan for concurrency-related claims.',\n    },\n    reportView: {\n      type: 'string',\n      enum: ['digest', 'full'],\n      description: 'digest (default) prints the readable body; full prints the structured report, which logicprobe_report_diff needs.',\n    },\n  },\n  output: {\n    schema: {\n      type: 'json',\n      description: 'Concurrency scan report with findings and summary.',\n    },\n    render(args, value) {\n      return [{ type: 'text' as const, text: renderReportText(value, { full: args.reportView === 'full' }) }]\n    },\n  },\n  timeoutMs: 10_000,\n  isConcurrencySafe: () => true,\n  async execute(args) {\n    return runConcurrencyScan(args.text) as unknown as JsonValue\n  },\n})\n"
    },
    {
      "path": "src/export-tool.ts",
      "content": "import { defineTool } from '@deepseek-ai/dsh-tools'\nimport type { JsonValue } from './json-value.js'\nimport { REPORT_SCHEMAS, DEFAULT_HASH_SPEC, modelHash, refusalVerdict, validateModel, verdictOf } from './engine.js'\nimport { exportModel, type ExportFormat } from './exporters.js'\nimport { renderReportText } from './report-view.js'\n\n/** The model hash of an export's input, when the input validates (the success path always does). */\nfunction exportHashes(model: unknown): { hashSpec: typeof DEFAULT_HASH_SPEC; modelHash?: string } {\n  const validation = validateModel(model)\n  return validation.ok\n    ? { hashSpec: DEFAULT_HASH_SPEC, modelHash: modelHash(validation.model) }\n    : { hashSpec: DEFAULT_HASH_SPEC }\n}\n\nexport const LOGICPROBE_EXPORT_TOOL_NAME = 'logicprobe_export'\n\n/**\n * DSH tool wrapping the external-tool exporters: turn a LogicModelV1 machine into\n * native input for the tool logicprobe routes to (UPPAAL / TLA+ / PRISM / SPIN).\n * v1 translates the core machine; unrepresentable invariants become warnings.\n */\nexport const logicProbeExportTool = defineTool({\n  name: LOGICPROBE_EXPORT_TOOL_NAME,\n  description:\n    'Export a LogicModelV1 state machine into native input for an external verification tool (logicprobe routing). format is one of uppaal (.xta + queries), tla (TLC spec + safety property), prism (.pm + .pctl), spin (Promela + ltl). Booleans are exported as 0/1 integers; invariants the target cannot express are returned as warnings, never silently dropped. Returns { ok, format, primary, extras?, warnings? } or { ok: false, error } when the model is invalid or the PRISM enumeration is too large.',\n  parameters: {\n    model: {\n      type: 'json',\n      required: true,\n      description: 'LogicModelV1 state-machine model to export.',\n    },\n    format: {\n      type: 'string',\n      required: true,\n      enum: ['uppaal', 'tla', 'prism', 'spin'],\n      description: 'Target tool format.',\n    },\n    reportView: {\n      type: 'string',\n      enum: ['digest', 'full'],\n      description: 'digest (default) prints the generated file verbatim; full prints the structured result as JSON.',\n    },\n  },\n  output: {\n    schema: {\n      type: 'json',\n      description: 'Export result with generated file content.',\n    },\n    render(args, value) {\n      return [{ type: 'text' as const, text: renderReportText(value, { full: args.reportView === 'full' }) }]\n    },\n  },\n  timeoutMs: 10_000,\n  isConcurrencySafe: () => true,\n  async execute(args) {\n    try {\n      const result = exportModel(args.model, args.format as ExportFormat)\n      const warnings = result.warnings ?? []\n      const nextSteps: string[] = []\n      if (warnings.length > 0) nextSteps.push('The target notation cannot express some invariants; the warnings name each one — verify them in the target tool rather than assuming they carried over.')\n      nextSteps.push('Run the exported file through its own tool (verify/compile) before trusting the translation; logicprobe guarantees the encoding, not the target checker\\'s verdict.')\n      return {\n        ok: true,\n        ran: true,\n        ...verdictOf(0, warnings.length),\n        schema: REPORT_SCHEMAS.export,\n        format: result.format,\n        primary: result.primary,\n        ...(result.extras === undefined ? {} : { extras: result.extras }),\n        hashes: exportHashes(args.model),\n        warnings,\n        nextSteps,\n      } as unknown as JsonValue\n    } catch (error) {\n      const message = error instanceof Error ? error.message : String(error)\n      return { ok: false, ran: false, ...refusalVerdict(message), schema: REPORT_SCHEMAS.export, errorCode: 'MODEL_INVALID', error: message } as unknown as JsonValue\n    }\n  },\n})\n"
    },
    {
      "path": "src/report-diff-tool.ts",
      "content": "import { defineTool } from '@deepseek-ai/dsh-tools'\nimport type { JsonValue } from './json-value.js'\nimport { diffReports } from './baseline.js'\nimport { renderReportText } from './report-view.js'\n\nexport const LOGICPROBE_REPORT_DIFF_TOOL_NAME = 'logicprobe_report_diff'\n\n/**\n * Model-visible DSH tool that compares two reports of the same family — the accepted\n * \"violations must not increase\" acceptance criterion, computed instead of eyeballed.\n * A finding's identity is its check + code + machine-readable locator, so a reworded\n * message reads as `changed`, and two runs over the same input add nothing.\n */\nexport const logicProbeReportDiffTool = defineTool({\n  name: LOGICPROBE_REPORT_DIFF_TOOL_NAME,\n  description:\n    'Compare two logicprobe reports of the same family: `baseline` (earlier) against `current` (newer). Use it to accept a slice by \"no new findings\". Findings match on a stable identity: check id, code, and a locator built from `evidence` and `path`. Reworded prose counts as `changed`, not as new. Returns added, removed and changed findings, plus `summary`. The `verdict` is about the delta: a newly added error finding fails it. `currentVerdict` keeps the run\\'s own verdict, so a clean delta over a failing report still shows as failing. Two runs over the same input add nothing.',\n  parameters: {\n    baseline: {\n      type: 'json',\n      required: true,\n      description: 'The earlier report (any family: verify, compose, datamodel, uml review, structure, concurrency).',\n    },\n    current: {\n      type: 'json',\n      required: true,\n      description: 'The current report to compare against the baseline.',\n    },\n    reportView: {\n      type: 'string',\n      enum: ['digest', 'full'],\n      description: 'digest (default) prints the readable body; full prints the structured diff report.',\n    },\n  },\n  output: {\n    schema: {\n      type: 'json',\n      description: 'Baseline diff report: added/removed/changed findings, delta verdict, current verdict, summary and next steps.',\n    },\n    render(args, value) {\n      return [{ type: 'text' as const, text: renderReportText(value, { full: args.reportView === 'full' }) }]\n    },\n  },\n  timeoutMs: 10_000,\n  isConcurrencySafe: () => true,\n  async execute(args) {\n    return diffReports(args.baseline, args.current) as unknown as JsonValue\n  },\n})\n"
    }
